def climbStairs(n: int) -> int:
    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1
    for step in range(2, n + 1):
        dp[step] = dp[step - 1] + dp[step - 2]
    return dp[n]

code.cpp:
int climbStairs(int n) {
    vector<int> dp(n + 1);
    dp[0] = dp[1] = 1;
    for (int step = 2; step <= n; ++step) {
        dp[step] = dp[step - 1] + dp[step - 2];
    }
    return dp[n];
}

